  color: var(--navy);
  margin-bottom: 1.25rem;
  text-align: center;
}

.benefits-list,
.initiatives-list,
.achievements-list {
  list-style: none;
}

.benefits-list li,
.initiatives-list li,
.achievements-list li {
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--gray-200);
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  font-size: 0.9375rem;
  color: var(--gray-700);
  line-height: 1.5;
}

.benefits-list li:last-child,
.initiatives-list li:last-child,
.achievements-list li:last-child { border-bottom: none; }

.list-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  margin-top: 0.125rem;
}

.list-icon-benefit { background: #d1fae5; color: #065f46; }
.list-icon-initiative { background: #dbeafe; color: #1e40af; }
.list-icon-achievement { background: #fef3c7; color: #92400e; }

/* FAQ Accordion */
.faq-section {
  padding: 2.5rem 0 3rem;
}

.faq-section h2 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 1.25rem;
  text-align: center;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-700);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  text-align: left;
  transition: color var(--transition);
}

.faq-question:hover { color: var(--navy); }

.faq-chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s ease;
}

.faq-item.open .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
  padding-bottom: 1rem;
}

.faq-answer p {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.7);
  padding: 3rem 1.25rem 2rem;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 700px;
  margin-bottom: 2rem;
}

.footer-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
  list-style: none;
}

.footer-links a {
  color: rgba(255,255,255,0.6);
  font-size: 0.8125rem;
  transition: color var(--transition);
}

.footer-links a:hover { color: var(--gold); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 1.5rem;
  font-size: 0.75rem;
  opacity: 0.5;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .search-bar { display: none; }
  .nav-links { display: none; }
  .hamburger { display: block; }

  .featured-card { aspect-ratio: auto; min-height: 260px; }
  .featured-card-content h2 { font-size: 1.25rem; }

  .article-grid { grid-template-columns: 1fr; }

  .header-inner { gap: 0.75rem; }

  .donate-hero h1 { font-size: 1.75rem; }
  .donate-hero { padding: 2.5rem 1.25rem; }

  .amount-tabs { grid-template-columns: repeat(4, 1fr); gap: 0.5rem; }
  .amount-tab { font-size: 1rem; padding: 0.75rem 0.25rem; }

  .footer-columns { grid-template-columns: 1fr; }

  .tag-page-header h1 { font-size: 1.5rem; }

  .learn-welcome h1 { font-size: 1.5rem; }

  .popular-tags-list { flex-wrap: nowrap; overflow-x: auto; padding-bottom: 0.5rem; }
}

@media (max-width: 480px) {
  .featured-card-content { padding: 1.25rem; }
  .featured-card-content h2 { font-size: 1.125rem; }
}

/* Thumbnail color placeholders */
.thumb-1 { background: linear-gradient(135deg, #1a1a3e, #4a2040); }
.thumb-2 { background: linear-gradient(135deg, #1e3a5f, #2d6a4f); }
.thumb-3 { background: linear-gradient(135deg, #0f2027, #203a43, #2c5364); }
